            .rev()
            .take_while(|&b| b != b'\n')
            .count()
            + 1;
        diagnostics.push(Diagnostic {
            rule_id,
            message: message.to_string(),
            severity: Severity::Error,
            byte_range: start..end,
            line,
            column,
            fix: None,
        });
    }
